function MenberInfoView:ctor(parentMain, parent, data, family_id, uid, roleType)
    self.parentMain = parentMain
    self.parent = parent
    self.data = data
    self.roleType = roleType
    self.family_id = family_id
    self.uid = uid
    local csbPath = "hall/res/FriendScircle/MenberInfoView/MenberInfoView.csb"
    MenberInfoView.super.ctor(self, csbPath)
    GameUtils.setNodeNameBindObj(self._csbNode)
    self:enableMask(true)
    self:initUI()
    self:initEvent()
end

