function MenberInfoView:initEvent()
    ReqMgr:addHandle("MenberInfoView", EVENTNAME)
    self.btn_add:onClick(handler(self, self.onClick_add))
    self.btn_give_master:onClick(handler(self, self.onClick_give_master))
    self.btn_del:onClick(handler(self, self.onClick_del))
    --调配成员
    self.btn_give_master_0:onClick(handler(self, self.onClick_fpyh))
    self.btn_give_master_0:setVisible(false)
    self.btn_xianzhi:onClick(handler(self, self.onClick_xianzhi))
    self.btn_guanli:onClick(handler(self, self.onClick_guanli))
    self.btn_game_result:onClick(handler(self, self.onClick_game_result))
end

function MenberInfoView:onClick_guanli( event )
    local isManager = self.data.isManager
    if isManager == 1 then
        isManager = 0
    else
        isManager = 1
    end
    local data = {
        playerId = self.uid,
        XYUid = USER_INFO.uid,
        groupId = self.family_id,
        status = isManager
    }
    ReqMgr:request(EVENTNAME.SET_CLUB_MANAGER_BY_OWNER, data, handler(self, self.SET_CLUB_MANAGER_BY_OWNER))

end

-- 查看这个玩家的战绩
function MenberInfoView:onClick_game_result(event)
    local searchId = self.uid
    local groupId = self.family_id
    local recordLayer = require("hall.familyCircle.ScoreRecordView").new(groupId, self.roleType, searchId)
    if recordLayer then
        recordLayer:addTo(self)
    end
end

function MenberInfoView:onClick_xianzhi( event )
    local isXianZhi = self.data.useClubStatus == 1
    local xianzhi = 1
    if isXianZhi then
        xianzhi = 0
    end
	require(HallServer_filePath):CLIENT_DISABLE_USER_GAME(self.family_id, self.uid, xianzhi)
    self.parent:InitGame()
    self:removeSelf()
end

function MenberInfoView:onClick_del( event )
    local function callFunc()
        local data = {
            playerId = self.uid,
            owerId = USER_INFO.uid,
            groupId = self.family_id,
        }
        ReqMgr:request(EVENTNAME.DELETE_PLAYER4_GROUPBY_OWER_ID, data, handler(self, self.DELETE_PLAYER4_GROUPBY_OWER_ID))
    end
    local data = {type = 2, title = "提示", content = "确定删除该成员？", callBackSure = callFunc} 
    require("hall.tips.CommonTips"):showTips(data)
end

function MenberInfoView:onClick_fpyh( event )
    local tip = '上级:' .. (self.data.upNickName or '') .. '(' .. (self.data.upUserId or '') .. ')' .. ';请输入新的上级ID'
    local addNumber = addNumber.new(handler(self, self.InvitePlayer), {tip = tip})
    self:addChild(addNumber)
end

function MenberInfoView:InvitePlayer(callData)

    local number = callData.number
    if not number then
        viewMgr:showTip({text = "操作失败..."})
        return
    end

    local data = {
        playerId = self.uid,
        newUpUid = number,
        groupId = self.family_id,
        interfaceType = "J"
    }
    ReqMgr:request(EVENTNAME.removeGroupPlayer2NewUp, data, handler(self , self.toOther))
end

function MenberInfoView:toOther( event )
    local netData = event.netData

	local data = netData.data

    if netData.returnCode == 0 then
        local root = self._csbNode.root
        root.txt_up_name:setString(data.upNickName or "无")
        root.txt_up_id:setString(data.upUserId or "无")
        self.data.upNickName = data.upNickName
        self.data.upUserId = data.upUserId
        viewMgr:showTip({text = '调配成功'})
    else
        -- 返回错误
        if netData.error then
            viewMgr:showTip({text = netData.error})
        else
            viewMgr:showTip({text = "分配失败..."})
        end
    end

    -- returnCode == 1
end

function MenberInfoView:onClick_add( event )
    local ishehuoren = not (tonumber(self.parentMain.owerId) == tonumber(USER_INFO["uid"]))
    local IntegralManagement = require("hall.familyCircle.IntegralManagement")
    IntegralManagement.new(self.family_id, self.parentMain, USER_INFO["uid"], ishehuoren, self.uid):addTo(self.parentMain)
end

function MenberInfoView:onClick_give_master( event )
    local function callFunc()
        local data = {
            assignor = self.uid,
            XYUid = USER_INFO.uid,
            groupId = self.family_id,
        }
        ReqMgr:request(EVENTNAME.TRANSFER_CLUB_OWNER, data, handler(self, self.TRANSFER_CLUB_OWNER))
    end
    local data = {type = 2, title = "提示", content = "是否转让该成员为盟主？", callBackSure = callFunc} 
    require("hall.tips.CommonTips"):showTips(data)
end

function MenberInfoView:TRANSFER_CLUB_OWNER(event)
    local netData = event.netData
	local param = event.param
	local returnCode = netData.returnCode
	local data = netData.data
    local error = netData.error
    if returnCode == 0 then
        viewMgr:showTip({text = "转让成功！"})
        if g_hallMainLayer then
            g_hallMainLayer:loadClub()
            if g_hallMainLayer.familyMainlayer and tonumber(self.family_id) == tonumber(g_hallMainLayer.familyMainlayer.family_id) then
                 g_hallMainLayer.familyMainlayer:removeSelf()
            end
         end
        -- self.parent:removeSelf()
        -- self.parentMain:InitGame(self.family_id)
    else
        viewMgr:showTip({text = error})
    end
end

function MenberInfoView:DELETE_PLAYER4_GROUPBY_OWER_ID(event)
    local netData = event.netData
	local param = event.param
	local returnCode = netData.returnCode
	local data = netData.data
    local error = netData.error
    if returnCode == 0 then
        viewMgr:showTip({text = "删除成员成功！"})
        self.parent:InitGame(self.parent.curPage, self.parent.searchUid)
        self:removeSelf()
        if g_hallMainLayer then
            g_hallMainLayer:loadClub()
        end
    else
        viewMgr:showTip({text = error})
    end
end

function MenberInfoView:SET_CLUB_MANAGER_BY_OWNER(event)
    local netData = event.netData
	local param = event.param
	local returnCode = netData.returnCode
	local data = netData.data
    local error = netData.error
    if returnCode == 0 then
        viewMgr:showTip({text = "操作成功！"})
        self.parent:InitGame(self.parent.curPage, self.parent.searchUid)
        self:removeSelf()
        if g_hallMainLayer then
            g_hallMainLayer:loadClub()
        end
    else
